import java
deprecated import experimental.semmle.code.java.frameworks.CredentialsInPropertiesFile

deprecated query predicate problems(CredentialsConfig cc, string message) {
  message = cc.getConfigDesc()
}

import java


class ExitOrHaltMethod extends Method {
  ExitOrHaltMethod() {
    exists(Class system | this.getDeclaringType() = system |
      this.hasName("exit") and
      system.hasQualifiedName("java.lang", ["System", "Runtime"])
      or
      this.hasName("halt") and
      system.hasQualifiedName("java.lang", "Runtime")
    )
  }
}


class ExitOrHaltMethodCall extends MethodCall {
  ExitOrHaltMethodCall() {
    exists(ExitOrHaltMethod exitMethod | this.getMethod() = exitMethod |
      exists(SourceMethodNotMainOrTest srcMethod | this = srcMethod.getACallSite(exitMethod))
    )
  }
}


class IntentionalExitMethodCall extends ExitOrHaltMethodCall {
  IntentionalExitMethodCall() {
    this.getMethod().hasName("exit") and
    this.getAnArgument() = this.getEnclosingCallable().getAParameter().getAnAccess()
  }
}


class SourceMethodNotMainOrTest extends Method {
  SourceMethodNotMainOrTest() {
    this.fromSource() and
    not this instanceof MainMethod and
    not (
      this.getEnclosingCallable*() instanceof LikelyTestMethod
      or
      this.getDeclaringType()
          .getEnclosingType*()
          .(LocalClassOrInterface)
          .getLocalTypeDeclStmt()
          .getEnclosingCallable() instanceof LikelyTestMethod
    )
  }
}

from ExitOrHaltMethodCall mc
where not mc instanceof IntentionalExitMethodCall
select mc,
  "Avoid calls to " + mc.getMethod().getDeclaringType().getName() + "." + mc.getMethod().getName() +
    "() as this prevents runtime cleanup and makes code harder to reuse."

import java

BlockStmt finallyBlock() { exists(TryStmt try | try.getFinally() = result) }

Stmt statementIn(BlockStmt finally) {
  finallyBlock() = finally and
  result.getParent+() = finally
}

predicate banned(Stmt s, BlockStmt finally) {
  s = statementIn(finally) and
  (
    s instanceof ReturnStmt
    or
    exists(ThrowStmt throw | s = throw and not throw.getLexicalCatchIfAny() = statementIn(finally))
    or
    exists(JumpStmt jump | s = jump and not jump.getTarget() = statementIn(finally))
  )
}

from Stmt s, BlockStmt finally
where banned(s, finally)
select s, "Leaving a finally-block with this statement can cause exceptions to silently disappear."

import java

predicate withinInitializer(Expr e) {
  e.getEnclosingCallable().hasName("<clinit>") or
  e.getEnclosingCallable() instanceof Constructor
}

predicate locallySynchronized(MethodCall ma) {
  ma.getEnclosingStmt().getEnclosingStmt+() instanceof SynchronizedStmt
}

predicate hasUnsynchronizedCall(Method m) {
  m.isPublic() and not m.isSynchronized()
  or
  exists(MethodCall ma, Method caller | ma.getMethod() = m and caller = ma.getEnclosingCallable() |
    hasUnsynchronizedCall(caller) and
    not caller.isSynchronized() and
    not locallySynchronized(ma)
  )
}

predicate withinLocalSynchronization(Expr e) {
  e.getEnclosingCallable().isSynchronized() or
  e.getEnclosingStmt().getEnclosingStmt+() instanceof SynchronizedStmt
}

class MyField extends Field {
  MyField() {
    this.fromSource() and
    not this.isFinal() and
    not this.isVolatile() and
    not this.getDeclaringType() instanceof EnumType
  }

  int getNumSynchedAccesses() {
    result =
      count(Expr synched | synched = this.getAnAccess() and withinLocalSynchronization(synched))
  }

  int getNumAccesses() { result = count(this.getAnAccess()) }

  float getPercentSynchedAccesses() {
    result = this.getNumSynchedAccesses().(float) / this.getNumAccesses()
  }
}

from MyField f, Expr e, int percent
where
  e = f.getAnAccess() and
  not withinInitializer(e) and
  not withinLocalSynchronization(e) and
  hasUnsynchronizedCall(e.getEnclosingCallable()) and
  f.getNumSynchedAccesses() > 0 and
  percent = (f.getPercentSynchedAccesses() * 100).floor() and
  percent > 80
select e,
  "Unsynchronized access to $@, but " + percent.toString() +
    "% of accesses to this field are synchronized.", f,
  f.getDeclaringType().getName() + "." + f.getName()

import java
import semmle.code.java.controlflow.Guards
import semmle.code.java.dataflow.SSA
import semmle.code.java.frameworks.Mockito

class LockType extends RefType {
  LockType() {
    this.getAMethod().hasName("lock") and
    this.getAMethod().hasName("unlock")
  }

  Method getLockMethod() {
    result.getDeclaringType() = this and
    (result.hasName("lock") or result.hasName("tryLock"))
  }

  Method getUnlockMethod() {
    result.getDeclaringType() = this and
    result.hasName("unlock")
  }

  Method getIsHeldByCurrentThreadMethod() {
    result.getDeclaringType() = this and
    result.hasName("isHeldByCurrentThread")
  }

  MethodCall getLockAccess() {
    result.getMethod() = this.getLockMethod() and

    not result instanceof MockitoVerifiedMethodCall
  }

  MethodCall getUnlockAccess() {
    result.getMethod() = this.getUnlockMethod() and

    not result instanceof MockitoVerifiedMethodCall
  }

  MethodCall getIsHeldByCurrentThreadAccess() {
    result.getMethod() = this.getIsHeldByCurrentThreadMethod() and

    not result instanceof MockitoVerifiedMethodCall
  }
}

predicate lockBlock(LockType t, BasicBlock b, int locks) {
  locks = strictcount(int i | b.getNode(i).asExpr() = t.getLockAccess())
}

predicate unlockBlock(LockType t, BasicBlock b, int unlocks) {
  unlocks = strictcount(int i | b.getNode(i).asExpr() = t.getUnlockAccess())
}


predicate lockUnlockBlock(LockType t, BasicBlock b, int netlocks) {
  lockBlock(t, b, netlocks) and not unlockBlock(t, b, _)
  or
  exists(int unlocks |
    not lockBlock(t, b, _) and unlockBlock(t, b, unlocks) and netlocks = -unlocks
  )
  or
  exists(int locks, int unlocks |
    lockBlock(t, b, locks) and unlockBlock(t, b, unlocks) and netlocks = locks - unlocks
  )
}


predicate failedLock(LockType t, BasicBlock lockblock, BasicBlock exblock) {
  exists(ControlFlowNode lock |
    lock = lockblock.getLastNode() and
    (
      lock.asExpr() = t.getLockAccess()
      or
      exists(SsaExplicitUpdate lockbool |

        lock.asExpr() = lockbool.getAUse() and
        lockbool.getDefiningExpr().(VariableAssign).getSource() = t.getLockAccess()
      )
    ) and
    (
      lock.getAnExceptionSuccessor() = exblock.getFirstNode() or
      lock.(ConditionNode).getAFalseSuccessor() = exblock.getFirstNode()
    )
  )
}


predicate heldByCurrentThreadCheck(LockType t, BasicBlock checkblock, BasicBlock falsesucc) {
  exists(ConditionBlock conditionBlock |
    conditionBlock.getCondition() = t.getIsHeldByCurrentThreadAccess()
  |
    conditionBlock = checkblock and
    conditionBlock.getTestSuccessor(false) = falsesucc
  )
}


predicate variableLockStateCheck(LockType t, BasicBlock checkblock, BasicBlock falsesucc) {
  exists(ConditionBlock conditionBlock, VarAccess v |
    v.getType() instanceof BooleanType and

    v.getVariable().getAnAssignedValue() = t.getLockAccess() and

    conditionBlock.getTestSuccessor(true) = t.getUnlockAccess().getBasicBlock() and
    conditionBlock.getCondition() = v
  |
    conditionBlock = checkblock and
    conditionBlock.getTestSuccessor(false) = falsesucc
  )
}


predicate blockIsLocked(LockType t, BasicBlock src, BasicBlock b, int locks) {
  lockUnlockBlock(t, b, locks) and src = b and locks > 0
  or
  exists(BasicBlock pred, int predlocks, int curlocks, int failedlock | pred = b.getAPredecessor() |

    blockIsLocked(t, src, pred, predlocks) and


    not heldByCurrentThreadCheck(t, pred, b) and
    not variableLockStateCheck(t, pred, b) and

    (if failedLock(t, pred, b) then failedlock = 1 else failedlock = 0) and
    (
      not lockUnlockBlock(t, b, _) and curlocks = 0
      or
      lockUnlockBlock(t, b, curlocks)
    ) and
    locks = predlocks + curlocks - failedlock and
    locks > 0 and

    locks < 10
  )
}

from Callable c, LockType t, BasicBlock src, ExitBlock exit, MethodCall lock
where

  t.getUnlockAccess().getEnclosingCallable() = c and
  blockIsLocked(t, src, exit, _) and
  exit.getEnclosingCallable() = c and
  lock = src.getANode().asExpr() and
  lock = t.getLockAccess()
select lock, "This lock might not be unlocked or might be locked more times than it is unlocked."

import java


class NullEQExpr extends ValueOrReferenceEqualsExpr {
  NullEQExpr() { exists(NullLiteral l | l.getParent() = this) }
}


class StaticFieldInit extends AssignExpr {
  StaticFieldInit() { exists(Field f | f.isStatic() | f.getAnAccess() = this.getDest()) }

  Field getField() { result.getAnAccess() = this.getDest() }

  IfStmt getAnEnclosingNullCheck() {
    result.getThen().getAChild*() = this.getEnclosingStmt() and
    result.getCondition().(NullEQExpr).getAChildExpr() = this.getField().getAnAccess()
  }

  IfStmt getNearestNullCheck() {
    result = this.getAnEnclosingNullCheck() and
    not result.getAChild+() = this.getAnEnclosingNullCheck()
  }
}


class LockObjectField extends Field {
  LockObjectField() {
    this.isStatic() and
    forex(Callable init | init = this.getAnAssignedValue().getEnclosingCallable() |
      init instanceof StaticInitializer
    )
  }
}


class ValidSynchStmt extends Stmt {
  ValidSynchStmt() {

    this.(SynchronizedStmt).getExpr().(TypeLiteral).getReferencedType() =
      this.getEnclosingCallable().getDeclaringType()
    or

    this.(SynchronizedStmt).getExpr().(FieldRead).getField() instanceof LockObjectField
    or

    exists(TryStmt try, LockObjectField lockField |
      this = try.getBlock() and
      lockField.getType().(RefType).hasQualifiedName("java.util.concurrent.locks", "ReentrantLock") and
      exists(MethodCall lockAction |
        lockAction.getQualifier() = lockField.getAnAccess() and
        lockAction.getMethod().getName() = "lock" and
        dominates(lockAction.getControlFlowNode(), this.getControlFlowNode())
      ) and
      exists(MethodCall unlockAction |
        unlockAction.getQualifier() = lockField.getAnAccess() and
        unlockAction.getMethod().getName() = "unlock" and
        postDominates(unlockAction.getControlFlowNode(), this.getControlFlowNode())
      )
    )
  }
}


class StaticMethod extends Method {
  StaticMethod() { this.isStatic() }

  predicate bodyIsSynchronized() {
    this.isSynchronized() or
    this.getBody().getAChild() instanceof ValidSynchStmt
  }
}

from StaticMethod method, IfStmt i, StaticFieldInit init, string message
where
  i = init.getNearestNullCheck() and
  method = i.getEnclosingCallable() and
  not method.bodyIsSynchronized() and
  not method instanceof StaticInitializer and

  exists(IfStmt unsyncNullCheck | unsyncNullCheck = init.getAnEnclosingNullCheck() |
    not unsyncNullCheck.getEnclosingStmt+() instanceof ValidSynchStmt
  ) and
  if i.getEnclosingStmt+() instanceof ValidSynchStmt
  then (
    not init.getField().isVolatile() and
    message = "The field must be volatile."
  ) else (
    if i.getEnclosingStmt+() instanceof SynchronizedStmt
    then message = "Bad synchronization."
    else message = "Missing synchronization."
  )
select init, "Incorrect lazy initialization of static field $@: " + message, init.getField() as f,
  f.getName()

import java

class WaitMethod extends Method {
  WaitMethod() {
    this.hasName("wait") and
    this.hasNoParameters() and
    this.getDeclaringType().hasQualifiedName("java.lang", "Object")
  }
}

class ConditionInterface extends Interface {
  ConditionInterface() { this.hasQualifiedName("java.util.concurrent.locks", "Condition") }
}

from MethodCall ma, ConditionInterface condition
where
  ma.getMethod() instanceof WaitMethod and
  ma.getQualifier().getType().(RefType).hasSupertype*(condition)
select ma, "Waiting for a condition should use Condition.await, not Object.wait."

import java

class RunMethod extends Method {
  RunMethod() {
    this.hasName("run") and
    this.hasNoParameters() and
    this.getDeclaringType().getAnAncestor().hasQualifiedName("java.lang", "Thread")
  }
}

from MethodCall m, RunMethod run
where
  m.getMethod() = run and
  not m.getEnclosingCallable() instanceof RunMethod
select m, "Calling 'Thread.run()' rather than 'Thread.start()' will not spawn a new thread."

import java


predicate isSynchronizedByBlock(Method m) {
  exists(SynchronizedStmt sync, Expr on | sync = m.getBody().getAChild*() and on = sync.getExpr() |
    if m.isStatic()
    then on.(TypeLiteral).getReferencedType() = m.getDeclaringType()
    else on.(ThisAccess).getType().(RefType).getSourceDeclaration() = m.getDeclaringType()
  )
}


pragma[nomagic]
predicate bothAccessVolatileField(Method set, Method get) {
  exists(Field f | f.isVolatile() |
    f = get.(GetterMethod).getField() and
    f.getAnAccess().(FieldWrite).getEnclosingCallable() = set
  )
}

from Method set, Method get
where
  set.getDeclaringType() = get.getDeclaringType() and
  set.getName().matches("set%") and
  get.getName() = "get" + set.getName().substring(3, set.getName().length()) and
  set.isSynchronized() and
  not (get.isSynchronized() or isSynchronizedByBlock(get)) and
  not bothAccessVolatileField(set, get) and
  set.fromSource()
select get, "This get method is unsynchronized, but the corresponding $@ is synchronized.", set,
  "set method"

import java


class ArrayCast extends CastExpr {
  ArrayCast() {
    this.getExpr() instanceof ArrayCreationExpr and
    this.getType() instanceof Array
  }


  Array getSourceType() { result = this.getExpr().getType() }


  Array getTargetType() { result = this.getType() }

  Type getSourceComponentType() { result = this.getSourceType().getComponentType() }

  Type getTargetComponentType() { result = this.getTargetType().getComponentType() }
}

predicate uncheckedCastType(RefType t) {
  t instanceof BoundedType or t instanceof ParameterizedType
}

predicate castFlow(ArrayCast ce, Variable v) {
  ce = v.getAnAssignedValue()
  or
  exists(Variable mid | castFlow(ce, mid) and mid.getAnAccess() = v.getAnAssignedValue())
}

predicate returnedFrom(ArrayCast ce, Method m) {
  exists(ReturnStmt ret | ret.getEnclosingCallable() = m | ret.getResult() = ce)
  or
  exists(Variable v | castFlow(ce, v) | returnedVariableFrom(v, m))
}

predicate returnedVariableFrom(Variable v, Method m) {
  exists(ReturnStmt ret | ret.getResult() = v.getAnAccess() and ret.getEnclosingCallable() = m)
}

predicate rawTypeConversion(RawType source, ParameterizedType target) {
  target.getErasure() = source.getErasure()
}

from ArrayCast ce, RefType target, RefType source, string message
where
  target = ce.getTargetComponentType() and
  source = ce.getSourceComponentType() and
  target.hasSupertype+(source) and
  not rawTypeConversion(source, target) and
  (

    not uncheckedCastType(target) and
    message =
      "Impossible downcast: the cast from " + source.getName() + "[] to " + target.getName() +
        "[] will always fail with a ClassCastException."
    or






    uncheckedCastType(target) and
    returnedFrom(ce, ce.getEnclosingCallable()) and
    ce.getEnclosingCallable().getReturnType().(Array).getElementType() = target and
    not ce.getEnclosingCallable().isPrivate() and
    message =
      "Impossible downcast: this is returned by " + ce.getEnclosingCallable().getName() +
        " as a value of type " + target.getName() + "[], but the array has type " + source.getName()
        + "[]. Callers of " + ce.getEnclosingCallable().getName() +
        " may fail with a ClassCastException."
    or
    exists(Method m, Variable v |
      uncheckedCastType(target) and
      castFlow(ce, v) and
      returnedVariableFrom(v, m) and
      m.getReturnType().(Array).getElementType() = target and
      not m.isPrivate() and
      message =
        "Impossible downcast: this is assigned to " + v.getName() + " which is returned by " + m +
          " as a value of type " + target.getName() + "[], but the array has type " +
          source.getName() + "[]. Callers of " + m.getName() +
          " may fail with a ClassCastException."
    )
  )
select ce, message

import java

EnumConstant nthMissing(SwitchStmt switch, int index) {
  not exists(switch.getDefaultCase()) and
  exists(EnumType enum |
    switch.getExpr().getType() = enum and
    result =
      rank[index](EnumConstant ec |
        ec.getDeclaringType() = enum and
        not switch.getAConstCase().getValue() = ec.getAnAccess()
      |
        ec order by ec.getName()
      )
  )
}

predicate first3(string msg, SwitchStmt switch, EnumConstant e1, EnumConstant e2, EnumConstant e3) {
  exists(int n | n = strictcount(nthMissing(switch, _)) |
    if n > 3
    then msg = "Switch statement does not have a case for $@, $@, $@, or " + (n - 3) + " more."
    else msg = "Switch statement does not have a case for $@, $@, or $@."
  ) and
  e1 = nthMissing(switch, 1) and
  e2 = nthMissing(switch, 2) and
  e3 = nthMissing(switch, 3)
}

predicate only2(string msg, SwitchStmt switch, EnumConstant e1, EnumConstant e2) {
  msg = "Switch statement does not have a case for $@ or $@." and
  e1 = nthMissing(switch, 1) and
  e2 = nthMissing(switch, 2)
}

predicate only1(string msg, SwitchStmt switch, EnumConstant e) {
  msg = "Switch statement does not have a case for $@." and
  e = nthMissing(switch, 1)
}

from string msg, SwitchStmt switch, EnumConstant e1, EnumConstant e2, EnumConstant e3
where
  if first3(_, switch, _, _, _)
  then first3(msg, switch, e1, e2, e3)
  else
    if only2(_, switch, _, _)
    then (
      only2(msg, switch, e1, e2) and e1 = e3
    ) else (
      only1(msg, switch, e1) and e1 = e2 and e1 = e3
    )
select switch, msg, e1, e1.getName(), e2, e2.getName(), e3, e3.getName()

import java

pragma[nomagic]
predicate mayThrow(Stmt s, RefType rt) {
  s.(ThrowStmt).getExpr().getType() = rt
  or
  exists(Call call |
    call.getEnclosingStmt() = s and
    call.getCallee().getAnException().getType() = rt
  )
}

pragma[nomagic]
predicate caughtBy(TryStmt try, Stmt s, RefType rt) {
  mayThrow(s, rt) and
  s.getEnclosingStmt+() = try.getBlock() and
  caughtType(try, _).hasSubtype*(rt)
}

pragma[nomagic]
predicate nestedTry(TryStmt outer, TryStmt inner) { inner.getEnclosingStmt+() = outer.getBlock() }


private predicate caughtInside(TryStmt t, Stmt s, RefType rt) {
  exists(TryStmt innerTry |
    nestedTry(t, innerTry) and
    caughtBy(innerTry, s, rt)
  )
}


private RefType getAThrownExceptionType(TryStmt t) {
  exists(Method m, Exception e |
    (
      m = t.getAResourceDecl().getAVariable().getType().(RefType).getAMethod() or
      m = t.getAResourceExpr().getType().(RefType).getAMethod()
    ) and
    m.hasName("close") and
    m.hasNoParameters() and
    m.getAnException() = e and
    result = e.getType()
  )
  or
  exists(Call call, Exception e |
    t.getBlock() = call.getEnclosingStmt().getEnclosingStmt*() or
    t.getAResourceDecl() = call.getEnclosingStmt()
  |
    (
      call.getCallee().getAnException() = e or
      call.(GenericCall).getATypeArgument(call.getCallee().getAnException().getType()) = e.getType()
    ) and
    not caughtInside(t, call.getEnclosingStmt(), e.getType()) and
    result = e.getType()
  )
  or
  exists(ThrowStmt ts |
    t.getBlock() = ts.getEnclosingStmt*() and
    not caughtInside(t, ts, ts.getExpr().getType()) and
    result = ts.getExpr().getType()
  )
}

private RefType caughtType(TryStmt try, int index) {
  exists(CatchClause cc | cc = try.getCatchClause(index) |
    if cc.isMultiCatch()
    then result = cc.getVariable().getTypeAccess().(UnionTypeAccess).getAnAlternative().getType()
    else result = cc.getVariable().getType()
  )
}

private predicate maybeUnchecked(RefType t) {
  t.getAnAncestor().hasQualifiedName("java.lang", "RuntimeException") or
  t.getAnAncestor().hasQualifiedName("java.lang", "Error") or
  t.hasQualifiedName("java.lang", "Exception") or
  t.hasQualifiedName("java.lang", "Throwable")
}

predicate overlappingExceptions(RefType e1, RefType e2) {
  exists(RefType throwable | throwable.hasQualifiedName("java.lang", "Throwable") |
    throwable.hasSubtype*(e1) and
    throwable.hasSubtype*(e2) and
    e1.getADescendant() = e2.getADescendant()
  )
}

from TryStmt try, int first, int second, RefType masking, RefType masked, string multiCatchMsg
where
  try.getFile().isJavaSourceFile() and
  masking = caughtType(try, first) and
  masking.getAStrictAncestor() = masked and
  masked = caughtType(try, second) and
  forall(RefType thrownType |
    thrownType = getAThrownExceptionType(try) and

    overlappingExceptions(thrownType, masked)
  |
    exists(RefType priorCaughtType, int priorIdx |
      priorIdx < second and
      priorCaughtType = caughtType(try, priorIdx) and
      thrownType.hasSupertype*(priorCaughtType)
    )
  ) and
  not maybeUnchecked(masked) and
  if try.getCatchClause(second).isMultiCatch()
  then multiCatchMsg = " for type " + masked.getName()
  else multiCatchMsg = ""
select try.getCatchClause(second),
  "This catch-clause is unreachable" + multiCatchMsg + "; it is masked $@.",
  try.getCatchClause(first),
  "by a previous catch-clause for exceptions of type '" + masking.getName() + "'"

import java
import Chaining

predicate exclude(Method m) {
  exists(string name | name = m.getName().toLowerCase() |
    name.matches("get%") or
    name.matches("is%") or
    name.matches("has%") or
    name.matches("add%")
  )
}


predicate checkExpr(MethodCall callToCheck, MethodCall otherCall, string operation, Variable v) {
  not exclude(otherCall.getMethod()) and
  v.getAnAssignedValue() = callToCheck and
  otherCall != callToCheck and
  otherCall.getMethod().getName() = operation and
  (
    otherCall.getAnArgument() = getChainedAccess(v) or
    otherCall.getQualifier() = getChainedAccess(v)
  )
}


predicate implicitCheckExpr(MethodCall callToCheck, string operation, Variable v) {
  exists(TryStmt try, LocalVariableDeclExpr decl |
    try.getAResourceDecl().getAVariable() = decl and
    decl.getVariable() = v and
    decl.getInit() = callToCheck and
    operation = "close"
  )
}


Expr getChainedAccess(Variable v) {
  result = v.getAnAccess()
  or
  exists(MethodCall chainedAccess | chainedAccess.getQualifier() = getChainedAccess(v) |
    designedForChaining(chainedAccess.getMethod()) and result = chainedAccess
  )
}


predicate checkedFunctionCall(MethodCall ma, string operation) {
  relevantFunctionCall(ma, _) and
  exists(Variable v | not v instanceof Field |
    v.getAnAssignedValue() = ma and
    (checkExpr(ma, _, operation, v) or implicitCheckExpr(ma, operation, v))
  )
}


predicate relevantFunctionCall(MethodCall ma, Method m) {
  ma.getMethod() = m and
  exists(Variable v | v.getAnAssignedValue() = ma) and
  not okToIgnore(ma)
}

predicate okToIgnore(MethodCall ma) { not ma.getCompilationUnit().fromSource() }

predicate functionStats(Method m, string operation, int used, int total, int percentage) {
  m.getReturnType() instanceof RefType and

  used = strictcount(MethodCall ma | checkedFunctionCall(ma, operation) and m = ma.getMethod()) and

  total = strictcount(MethodCall ma | relevantFunctionCall(ma, m)) and
  percentage = used * 100 / total
}

from MethodCall unchecked, Method m, string operation, int percent
where
  relevantFunctionCall(unchecked, m) and
  not checkedFunctionCall(unchecked, operation) and
  functionStats(m, operation, _, _, percent) and
  percent >= 90 and
  not m.getName() = operation and
  not unchecked.getEnclosingStmt().(ExprStmt).isFieldDecl()
select unchecked,
  "After " + percent.toString() + "% of calls to " + m.getName() + " there is a call to " +
    operation + " on the return value. The call may be missing in this case."

import java


class DangerousExpression extends Expr {
  DangerousExpression() {
    exists(Expr e | this = e.getParent*() |
      e instanceof MethodCall or
      e instanceof ArrayAccess or
      exists(e.(FieldAccess).getQualifier())
    )
  }
}


class NonShortCircuit extends BinaryExpr {
  NonShortCircuit() {
    (
      this instanceof AndBitwiseExpr or
      this instanceof OrBitwiseExpr
    ) and
    this.getLeftOperand().getType().hasName("boolean") and
    this.getRightOperand().getType().hasName("boolean") and
    this.getRightOperand() instanceof DangerousExpression
